#ifndef SHARED_CANONICAL_REPLAY_VALIDATION_HPP
#define SHARED_CANONICAL_REPLAY_VALIDATION_HPP
#include "CanonicalSnapshot.hpp"
#include <cstring>
namespace canonical {
inline void schemaNeed(bool ok,const char* label){if(!ok)throw std::runtime_error(label);}
inline void keys(const json& v,std::initializer_list<const char*> names){schemaNeed(v.is_object()&&v.size()==names.size(),"complete shared object keys");for(const auto* n:names)schemaNeed(v.contains(n),"missing shared required key");}
inline void nativeReal(const json& v){schemaNeed(v.is_number_float()&&std::isfinite(v.get<double>()),"shared finite native real required");}
inline void nativeInt(const json& v,int lo,int hi){schemaNeed(v.is_number_integer()&&!v.is_boolean(),"shared native integer required");if(v.is_number_unsigned()){const auto n=v.get<std::uint64_t>();schemaNeed(hi>=0&&n<=static_cast<std::uint64_t>(hi)&&(lo<=0||n>=static_cast<std::uint64_t>(lo)),"shared unsigned lower/upper range without narrowing");}else{const auto n=v.get<std::int64_t>();schemaNeed(n>=lo&&n<=hi,"shared integer range");}}
inline void nativeVector(const json& v,std::size_t count){schemaNeed(v.is_array()&&v.size()==count,"shared vector width");for(const auto& x:v)nativeReal(x);}
inline void nativeMatrix(const json& v,std::size_t rows,std::size_t cols){schemaNeed(v.is_array()&&v.size()==rows,"shared matrix rows");for(const auto& x:v)nativeVector(x,cols);}
inline bool nativeBitsEqual(const json& a,const json& b){
    if(a.is_number_integer()&&b.is_number_integer())return a.dump()==b.dump();
    if(a.type()!=b.type())return false;
    if(a.is_number_float()){double x=a.get<double>(),y=b.get<double>();return std::isfinite(x)&&std::isfinite(y)&&std::memcmp(&x,&y,sizeof(double))==0;}
    if(a.is_array()){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(!nativeBitsEqual(a[i],b[i]))return false;return true;}
    if(a.is_object()){if(a.size()!=b.size())return false;for(auto it=a.begin();it!=a.end();++it)if(!b.contains(it.key())||!nativeBitsEqual(it.value(),b.at(it.key())))return false;return true;}
    return a==b;
}
inline void nativeIds(const json& v,int lo,int hi){schemaNeed(v.is_array(),"shared ID array");std::set<int> seen;for(const auto& x:v){nativeInt(x,lo,hi);schemaNeed(seen.insert(x.get<int>()).second,"shared duplicate ID");}}
inline void nativeBitmap(const json& v){schemaNeed(v.is_string(),"shared bitmap string");const auto s=v.get<std::string>();schemaNeed(s.size()==22500&&s.find_first_not_of("0123456789abcdef")==std::string::npos,"shared bitmap full bytes");}
inline void replayGraph(const json& v,int id,const json& bases,bool points){
    if(points)keys(v,{"id","anchorIds","baseIds","anchorPoints"});else keys(v,{"id","anchorIds","baseIds"});nativeInt(v.at("id"),1,14);schemaNeed(v.at("id").get<int>()==id,"shared graph owner");nativeIds(v.at("anchorIds"),1,14);nativeIds(v.at("baseIds"),0,2);
    if(points){schemaNeed(v.at("anchorPoints").is_array()&&v.at("anchorPoints").size()==v.at("baseIds").size(),"shared full ordered basepoints");for(std::size_t j=0;j<v.at("baseIds").size();++j){nativeVector(v.at("anchorPoints").at(j),2);const auto& b=bases.at(v.at("baseIds").at(j).get<int>());json expected={b.at(0).get<double>(),b.at(1).get<double>()};schemaNeed(nativeBitsEqual(v.at("anchorPoints").at(j),expected),"shared native basepoint bits");}}
}
inline const std::vector<std::string>& commonSettingsKeys(){static const std::vector<std::string> k={"num","dim","model","model-params","world","bases","formation","searching","position_covariance","initial"};return k;}
inline const std::set<std::string>& separateSettingsKeys(){static const std::set<std::string> k={"uncertainty","optimiser","cbfs","execute","debug","output_path","run_suffix","tvt-experiment","estimator-in-loop","all","id","canonical-replay-state","cano-pcg","periodic-target-interface"};return k;}
inline void sourceIntPoint(const json& p){schemaNeed(p.is_array()&&p.size()==2,"shared config coordinate2");for(const auto& x:p)nativeInt(x,-2000,2000);}
inline void validateCommonSettings(const json& cfg){
    schemaNeed(cfg.is_object(),"full shared source/common config object");for(const auto& k:commonSettingsKeys())schemaNeed(cfg.contains(k),"missing consumed shared common setting");
    for(auto it=cfg.begin();it!=cfg.end();++it)schemaNeed(std::find(commonSettingsKeys().begin(),commonSettingsKeys().end(),it.key())!=commonSettingsKeys().end()||separateSettingsKeys().count(it.key()),"undeclared method/solver/bookkeeping setting requires extension");
    nativeInt(cfg.at("num"),14,14);nativeInt(cfg.at("dim"),4,4);schemaNeed(cfg.at("model").is_string()&&cfg.at("model")=="SingleIntegrate2D","shared source model name");keys(cfg.at("model-params"),{"discharge-rate"});nativeReal(cfg.at("model-params").at("discharge-rate"));
    const auto& w=cfg.at("world");keys(w,{"boundary","charge","spacing"});nativeReal(w.at("spacing"));schemaNeed(w.at("boundary").is_array()&&w.at("boundary").size()==4,"shared world boundary4");for(const auto& p:w.at("boundary"))sourceIntPoint(p);
    schemaNeed(w.at("charge").is_array()&&w.at("charge").size()==3,"shared charge regions3");for(const auto& c:w.at("charge")){keys(c,{"position","radius","charge-rate"});sourceIntPoint(c.at("position"));nativeReal(c.at("radius"));nativeReal(c.at("charge-rate"));}
    const auto& bases=cfg.at("bases");schemaNeed(bases.is_array()&&bases.size()==3,"shared bases3 config");for(const auto& b:bases)sourceIntPoint(b);
    const auto& f=cfg.at("formation");keys(f,{"parts","bases-id"});nativeInt(f.at("parts"),2,2);schemaNeed(f.at("bases-id").is_array()&&f.at("bases-id").size()==2,"shared source base parts2");for(const auto& b:f.at("bases-id")){schemaNeed(b.is_array()&&b.size()==2,"shared two ordered bases");nativeIds(b,0,2);}
    const auto& searching=cfg.at("searching");keys(searching,{"//method","method","downward","front-sector","front-cone"});schemaNeed(searching.at("method").is_string()&&searching.at("//method").is_array(),"shared searching selectors");for(const auto& x:searching.at("//method"))schemaNeed(x.is_string(),"shared search comment selector string");
    keys(searching.at("downward"),{"radius"});nativeReal(searching.at("downward").at("radius"));keys(searching.at("front-sector"),{"inner-radius","outer-radius","half-angle-deg"});for(const auto& x:searching.at("front-sector"))nativeReal(x);keys(searching.at("front-cone"),{"height","downward-radius","camera-pitch-deg"});for(const auto& x:searching.at("front-cone"))nativeReal(x);
    const auto& cov=cfg.at("position_covariance");keys(cov,{"enable","ranging_sigma","//uncertainty-type","uncertainty-type","reference-selection"});schemaNeed(cov.at("enable").is_boolean(),"shared covariance enabled bool");nativeReal(cov.at("ranging_sigma"));schemaNeed(cov.at("//uncertainty-type").is_array()&&cov.at("uncertainty-type").is_string()&&cov.at("reference-selection").is_string(),"shared covariance selectors");for(const auto& x:cov.at("//uncertainty-type"))schemaNeed(x.is_string(),"shared covariance comment string");
    const auto& initial=cfg.at("initial");keys(initial,{"position","battery","yawDeg"});nativeInt(initial.at("yawDeg"),90,90);keys(initial.at("battery"),{"min","max"});nativeInt(initial.at("battery").at("min"),4100,4100);nativeInt(initial.at("battery").at("max"),4200,4200);
    const auto& position=initial.at("position");keys(position,{"method","positions"});schemaNeed(position.at("method").is_string()&&position.at("method")=="specified"&&position.at("positions").is_array()&&position.at("positions").size()==14,"shared specified positions14");for(const auto& p:position.at("positions"))nativeVector(p,2);
}
inline json commonSettingsProjection(const json& cfg){validateCommonSettings(cfg);json out=json::object();for(const auto& k:commonSettingsKeys())out[k]=cfg.at(k);return out;}
inline void validateReplayReceipt(const json& receipt){
    keys(receipt,{"schema","phase","binding","nodes","swarm_config_copy","world","bases","grid","true_evaluation_map_phase","true_valid_hex","true_visited_hex","reset_history","charge_policy","counts","method_solver_and_PCG_warm_state"});
    schemaNeed(receipt.at("schema")=="shared-native-capture-receipt-v1"&&receipt.at("phase")=="post-declared-comm-covariance-fixedgraph-bootstrap/pre-estimator-sensor-target-control","shared complete replay phase");
    const auto& binding=receipt.at("binding");keys(binding,{"plan_sha256","source_index_sha256","source_archive_sha256","capture_binary_sha256","capture_config_sha256","environment_sha256","seed","release_sha256","dispatch_sha256"});nativeInt(binding.at("seed"),1,2147483647);
    for(const char* k:{"plan_sha256","source_index_sha256","source_archive_sha256","capture_binary_sha256","capture_config_sha256","environment_sha256","release_sha256","dispatch_sha256"}){schemaNeed(binding.at(k).is_string(),"shared source SHA string");const auto s=binding.at(k).get<std::string>();schemaNeed(s.size()==64&&s.find_first_not_of("0123456789abcdef")==std::string::npos,"shared source SHA bytes");}
    const auto& counts=receipt.at("counts");keys(counts,{"robot_constructor_attempts","robot_constructor_returns","repo_environment_factory_attempts","environment_start_completed","repo_rand_attempts","repo_rand_returns","opaque_process_RNG_calls","optimize_API_calls","trajectory_calls","target_calls","hold_calls","producer_PCG_calls","zero_scope_proof"});for(const char* k:{"robot_constructor_attempts","robot_constructor_returns","repo_rand_attempts","repo_rand_returns"})nativeInt(counts.at(k),14,14);for(const char* k:{"repo_environment_factory_attempts","environment_start_completed"})nativeInt(counts.at(k),15,15);for(const char* k:{"optimize_API_calls","trajectory_calls","target_calls","hold_calls","producer_PCG_calls"})nativeInt(counts.at(k),0,0);schemaNeed(counts.at("opaque_process_RNG_calls").is_null()&&counts.at("zero_scope_proof")=="CANONICAL_CAPTURE_ONLY compile guards reject these entry points before scientific work","shared capture count domains");
    const auto& cfg=receipt.at("swarm_config_copy");validateCommonSettings(cfg);
    schemaNeed(nativeBitsEqual(receipt.at("world"),cfg.at("world"))&&nativeBitsEqual(receipt.at("bases"),cfg.at("bases")),"shared world/bases source join");
    schemaNeed(receipt.at("bases").is_array()&&receipt.at("bases").size()==3,"shared bases3");
    schemaNeed(nativeBitsEqual(receipt.at("grid"),json{{"xNum",300},{"yNum",300},{"xLim",{-1500.,1500.}},{"yLim",{-1500.,1500.}}}),"shared canonical grid");
    schemaNeed(receipt.at("reset_history").is_array()&&receipt.at("reset_history").empty(),"shared reset exclusion");
    schemaNeed(receipt.at("true_evaluation_map_phase")=="pre-sensor isolated true map"&&receipt.at("charge_policy")=="original native discharge; charge setter only in optimise, not invoked by capture; checkCharge original before any future hold"&&receipt.at("method_solver_and_PCG_warm_state")=="fresh per method, not inherited/shared warmstart","shared declared state phase policies");
    for(const char* k:{"true_valid_hex","true_visited_hex"})nativeBitmap(receipt.at(k));
    schemaNeed(receipt.at("true_valid_hex")==std::string(22500,'f')&&receipt.at("true_visited_hex")==std::string(22500,'0'),"shared isolated true map bits");
    const auto& nodes=receipt.at("nodes");schemaNeed(nodes.is_array()&&nodes.size()==14,"shared complete14 nodes");
    for(std::size_t i=0;i<nodes.size();++i){const auto& n=nodes.at(i);const int id=static_cast<int>(i)+1;
        keys(n,{"id","state","X_x_y_battery_yaw","u0","velocity","runtime_s","drift_f","control_g","settings_copy","formation","covariance_formation","part_id","id_in_part","neighbours","base_ids","position_covariance","uncertainty_history","rate_certificate","certificate_version","allocation_version","estimator_active","estimator_frame","map_phase","valid_hex","visited_hex","comm","excluded_consumed_state"});
        nativeInt(n.at("id"),1,14);schemaNeed(n.at("id").get<int>()==id,"shared ordered IDs");keys(n.at("state"),{"x","y","battery","yawRad"});for(const auto& x:n.at("state"))nativeReal(x);
        nativeVector(n.at("X_x_y_battery_yaw"),4);schemaNeed(nativeBitsEqual(n.at("X_x_y_battery_yaw"),json{n.at("state").at("x"),n.at("state").at("y"),n.at("state").at("battery"),n.at("state").at("yawRad")}),"shared X4 bits");keys(n.at("u0"),{"vx","vy","yawRateRad"});for(const auto& x:n.at("u0")){nativeReal(x);schemaNeed(nativeBitsEqual(x,json(0.)),"shared zero u0");}
        nativeVector(n.at("velocity"),2);schemaNeed(nativeBitsEqual(n.at("velocity"),json{0.,0.}),"shared zero velocity2");nativeReal(n.at("runtime_s"));schemaNeed(nativeBitsEqual(n.at("runtime_s"),json(0.)),"shared runtime0");nativeVector(n.at("drift_f"),4);nativeMatrix(n.at("control_g"),4,3);
        schemaNeed(nativeBitsEqual(commonSettingsProjection(n.at("settings_copy")),commonSettingsProjection(cfg)),"complete native common settings including initial join");
        nativeInt(n.at("part_id"),1,14);nativeInt(n.at("id_in_part"),1,14);nativeIds(n.at("neighbours"),1,14);nativeIds(n.at("base_ids"),0,2);replayGraph(n.at("formation"),id,receipt.at("bases"),true);replayGraph(n.at("covariance_formation"),id,receipt.at("bases"),false);nativeMatrix(n.at("position_covariance"),2,2);
        const auto& u=n.at("uncertainty_history");keys(u,{"previous","current","rate","present"});for(const char* k:{"previous","current","rate"})nativeReal(u.at(k));schemaNeed(u.at("present").is_boolean(),"shared history bool");
        const auto& c=n.at("rate_certificate");keys(c,{"robot_id","snapshot_version","information","covariance","epsilon","information_rate_bound","covariance_rate_bound","epsilon_rate_bound","frozen_references"});nativeInt(c.at("robot_id"),0,14);nativeInt(c.at("snapshot_version"),0,0);nativeMatrix(c.at("information"),2,2);nativeMatrix(c.at("covariance"),2,2);for(const char* k:{"epsilon","information_rate_bound","covariance_rate_bound","epsilon_rate_bound"})nativeReal(c.at(k));schemaNeed(c.at("frozen_references").is_array(),"shared frozen refs");for(const auto& r:c.at("frozen_references")){keys(r,{"reference_id","direction","effective_variance"});nativeInt(r.at("reference_id"),-3,14);nativeVector(r.at("direction"),2);nativeReal(r.at("effective_variance"));}
        for(const char* k:{"certificate_version","allocation_version"})nativeInt(n.at(k),0,0);schemaNeed(n.at("estimator_active").is_boolean()&&!n.at("estimator_active").get<bool>()&&n.at("estimator_frame").is_null()&&n.at("map_phase")=="pre-estimate/pre-sensor","shared estimator/map phase");for(const char* k:{"valid_hex","visited_hex"})nativeBitmap(n.at(k));schemaNeed(n.at("valid_hex")==std::string(22500,'f')&&n.at("visited_hex")==std::string(22500,'0'),"shared node map bits");
        const json excluded={{"certificate_available",false},{"local_snapshot_present",false},{"last_hard_problem_present",false},{"last_hard_problem_hash",""},{"committed_version",0},{"committed_valid",false},{"committed_node_versions",0},{"committed_endpoints",0},{"committed_hard_problems",0},{"committed_certificates",0}};schemaNeed(nativeBitsEqual(n.at("excluded_consumed_state"),excluded),"shared consumed state exclusion");
        const auto& comm=n.at("comm");keys(comm,{"positions","velocities","yaw","battery","covariance","uncertainty_rate","excluded_endpoint_dictionary_sizes"});schemaNeed(nativeBitsEqual(comm.at("excluded_endpoint_dictionary_sizes"),json{{"snapshots",0},{"epsilon",0},{"bar_nu",0},{"rate",0},{"version",0},{"allocation",0}}),"shared endpoint dictionary empty");
        for(const char* k:{"positions","velocities","yaw","battery","covariance","uncertainty_rate"}){const auto& values=comm.at(k);schemaNeed(values.is_array()&&values.size()==14,"shared complete comm14");for(std::size_t j=0;j<14;++j){keys(values.at(j),{"id","value"});nativeInt(values.at(j).at("id"),1,14);schemaNeed(values.at(j).at("id").get<int>()==static_cast<int>(j)+1,"shared comm order");const auto& v=values.at(j).at("value");const std::string channel(k);if(channel=="positions"||channel=="velocities")nativeVector(v,2);else if(channel=="covariance")nativeMatrix(v,2,2);else nativeReal(v);}}
    }
}
}
#endif
